// Упрощённый Java-псевдокод: claimOrRead фиксирует claim в БД.
PaymentResult pay(Tenant t, String key, PaymentCommand cmd) {
    String fingerprint = canonicalFingerprint(cmd);
    Claim claim = repository.claimOrRead(t, key, fingerprint);
    if (claim.mismatch()) throw new IntentConflict();
    if (claim.completed()) return claim.savedResult();
    if (!claim.owned()) throw new StillProcessing();

    // SQL-транзакция закрыта; провайдер — отдельная система.
    ProviderResult result = provider.charge(cmd, stableProviderKey(t, key));
    return repository.complete(t, key, result);
}
